<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('reports.view');$pdo=db();$bid=(int)$u['business_id'];$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-d')));$validDate=fn($d)=>preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)===1;if(!$validDate($from)||!$validDate($to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}$q=$pdo->prepare("SELECT COUNT(*) count,COALESCE(SUM(total),0) billed,COALESCE(SUM(amount_paid),0) collected FROM invoices WHERE business_id=? AND status<>'Void' AND invoice_date BETWEEN ? AND ?");$q->execute([$bid,$from,$to]);$f=$q->fetch();$q=$pdo->prepare('SELECT COUNT(*) count,COALESCE(SUM(amount),0) total FROM payments WHERE business_id=? AND reversed_at IS NULL AND paid_at BETWEEN ? AND ?');$q->execute([$bid,$from,$to]);$p=$q->fetch();$q=$pdo->prepare('SELECT COUNT(*) count,COALESCE(SUM(amount),0) total FROM expenses WHERE business_id=? AND expense_date BETWEEN ? AND ?');$q->execute([$bid,$from,$to]);$x=$q->fetch();$q=$pdo->prepare("SELECT c.name,COUNT(i.id) invoices,COALESCE(SUM(CASE WHEN i.status<>'Void' THEN i.total ELSE 0 END),0) billed,COALESCE(SUM(CASE WHEN i.status<>'Void' THEN i.total-i.amount_paid ELSE 0 END),0) outstanding FROM customers c LEFT JOIN invoices i ON i.customer_id=c.id AND i.invoice_date BETWEEN ? AND ? WHERE c.business_id=? AND c.archived_at IS NULL GROUP BY c.id ORDER BY billed DESC LIMIT 8");$q->execute([$from,$to,$bid]);$customers=$q->fetchAll();if(($_GET['export']??'')==='customers'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="buznet-customer-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Customer','Invoices','Billed','Outstanding']);foreach($customers as $c)fputcsv($out,[$c['name'],$c['invoices'],$c['billed'],$c['outstanding']]);fclose($out);exit;}page_start('Reports','reports');module_css('reports');?><div class="section-head"><div><span class="eyebrow">BUSINESS PULSE</span><h1>Reports</h1><p>A grounded view of your billing, collections and operating costs.</p></div></div><form class="toolbar content-card" style="margin-bottom:14px"><label class="help-text">From <input class="search" type="date" name="from" value="<?=e($from)?>"></label><label class="help-text">To <input class="search" type="date" name="to" value="<?=e($to)?>"></label><button class="button primary">Apply period</button><a class="button secondary" href="reports.php?from=<?=e($from)?>&to=<?=e($to)?>&export=customers">Export customers CSV</a></form><div class="summary-grid"><div class="summary-tile"><small>Invoiced</small><strong><?=money($f['billed'])?></strong><span class="help-text"><?=$f['count']?> invoices</span></div><div class="summary-tile"><small>Cash collected</small><strong><?=money($p['total'])?></strong><span class="help-text"><?=$p['count']?> receipts</span></div><div class="summary-tile"><small>Expenses</small><strong><?=money($x['total'])?></strong><span class="help-text"><?=$x['count']?> records</span></div></div><div class="content-card"><div class="panel-head"><div><h2>Customer billing summary</h2><p><?=fmt_date($from)?> – <?=fmt_date($to)?></p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>CUSTOMER</th><th>INVOICES</th><th>BILLED</th><th>OUTSTANDING</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td class="table-strong"><?=e($c['name'])?></td><td><?=$c['invoices']?></td><td><?=money($c['billed'])?></td><td><?=money($c['outstanding'])?></td></tr><?php endforeach;if(!$customers):?><tr><td colspan="4" class="empty-row">No customer activity in this period.</td></tr><?php endif?></tbody></table></div></div><?php page_end();
